from datetime import date, timedelta

# Feriados/sem expediente — Campinas/TJSP 2026-2027 (library/calendario_forense_campinas.md)
feriados = {
    date(2026,11,20): "Consciência Negra (Lei 14.759/2023)",
    date(2026,12,8):  "N. Sra. da Conceição — feriado municipal Campinas",
    date(2026,12,24): "sem expediente forense",
    date(2026,12,25): "Natal",
    date(2026,12,31): "sem expediente forense",
    date(2027,1,1):   "Confraternização Universal",
    date(2027,2,8):   "Carnaval",
    date(2027,2,9):   "Carnaval",
}
# 25/01/2027: feriado APENAS Capital — NÃO se aplica a Campinas (dia útil aqui)
recesso = (date(2026,12,20), date(2027,1,20))  # CPC art. 220, inclusive

def util(d):
    return d.weekday() < 5 and d not in feriados and not (recesso[0] <= d <= recesso[1])

def dia_util_seguinte(d):
    d += timedelta(days=1)
    while not util(d): d += timedelta(days=1)
    return d

def nome(d):
    return d.strftime("%a") + " " + d.strftime("%d/%m/%Y")

# --- Disponibilizações (PDFs) ---
for disp in (date(2026,11,19), date(2026,12,10)):
    print("disponibilizacao:", nome(disp))
    pub = disp
    while True:
        pub += timedelta(days=1)
        if util(pub): break   # 1o dia útil seguinte à disponibilização (art. 4º §3 / 224 §2)
    ini = dia_util_seguinte(pub)  # 1o dia útil seguinte à publicação (§4 / 224 §3)
    print("  publicacao:", nome(pub), "| inicio contagem:", nome(ini))

def contagem(inicio, n):
    dias, d, usados = [], inicio, 0
    while usados < n:
        if util(d):
            usados += 1
            dias.append((usados, d))
        d += timedelta(days=1)
    return dias

for label, ini, n in [("contestacao 15d", date(2026,11,24), 15),
                      ("embargos 5d", date(2026,12,14), 5),
                      ("apelacao 15d", date(2026,12,14), 15),
                      ("[HIPOTETICO] contestacao 30d (dobro)", date(2026,11,24), 30)]:
    dias = contagem(ini, n)
    print(f"\n{label}: vencimento {nome(dias[-1][1])}")
    print("  " + " | ".join(f"{i}:{d.strftime('%d/%m')}" for i, d in dias))

# dias pulados (não úteis) dentro das janelas de contagem
def pulados(ini, fim):
    d, out = ini, []
    while d <= fim:
        if not util(d):
            r = "fim de semana" if d.weekday() >= 5 else feriados.get(d, "")
            if recesso[0] <= d <= recesso[1]: r = (r + " + recesso art.220").strip(" +")
            out.append((d, r))
        d += timedelta(days=1)
    return out

print("\n--- pulados na contestacao (24/11-15/12/2026) ---")
for d, r in pulados(date(2026,11,24), date(2026,12,15)): print(nome(d), "-", r)
print("\n--- pulados na apelacao (14/12/2026-03/02/2027) ---")
for d, r in pulados(date(2026,12,14), date(2027,2,3)): print(nome(d), "-", r)
print("\n25/01/2027 util em Campinas?", util(date(2027,1,25)))
EOF
